  additionalFilters?: string | undefined;
  aggregation?: SecurityMonitoringRuleQueryAggregation | undefined;
  /** Fields used to correlate results across queries in sequence detection rules. */
  correlatedByFields?: HistoricalJobQueryCorrelatedByFieldsList | undefined;
  /** Zero-based index of the query to correlate with in sequence detection rules. Up to 10 queries are supported, so valid values are 0 to 9. */
  correlatedQueryIndex?: number | undefined;
  /** Custom query extension used to refine the base query. */
  customQueryExtension?: string | undefined;
  dataSource?: SecurityMonitoringStandardDataSource | undefined;
  /** IDs of reference datasets used by this query. */
  datasetIds?: HistoricalJobQueryDatasetIdsList | undefined;
  /** Version of each dataset used by the job, keyed by dataset ID. Pinned when the job is created. */
  datasetVersions?: HistoricalJobQueryDatasetVersionsMap | undefined;
  /** Field for which the cardinality is measured. Sent as an array. */
  distinctFields?: HistoricalJobQueryDistinctFieldsList | undefined;
  /** Fields to group by. */
  groupByFields?: HistoricalJobQueryGroupByFieldsList | undefined;
  /** When false, events without a group-by value are ignored by the query. When true, events with missing group-by fields are processed with `N/A`, replacing the missing values. */
  hasOptionalGroupByFields?: boolean | undefined;
  /** Index used to load the data for this query. */
  index?: string | undefined;
  /** Indexes used to load the data for this query. Mutually exclusive with `index`. */
  indexes?: HistoricalJobQueryIndexesList | undefined;
  /** (Deprecated) The target field to aggregate over when using the sum or max aggregations. Use the `metrics` field instead. */
  metric?: string | undefined;
  /** Group of target fields to aggregate over when using the sum, max, geo data, or new value aggregations. The sum, max, and geo data aggregations only accept one value in this list, whereas the new value aggregation accepts up to five values. */
  metrics?: HistoricalJobQueryMetricsList | undefined;
  /** Name of the query. */
  name?: string | undefined;
  /** Query to run on logs. */
  query?: string | undefined;
  /** Language used to parse the query string. */
